select count(*) from integration_schema.job_run
where status in ('PENDING','RUNNING','CANCEL_REQUESTED')
and job_code=#{jobCode}

select * from integration_schema.job_run
job_code=#{jobCode}
order by created_at desc limit #{size} offset #{offset}
